from django.db import migrations, models


def criar_entradas_das_alunas_antigas(apps, schema_editor):
    """Cada turma que a aluna já tem vira uma entrada na data da matrícula (= "aluna nova").
    Não muda nenhum valor de mensalidade: alunas sem PrecoAluna continuam com valor manual."""
    Aluna = apps.get_model('usuarios', 'Aluna')
    EntradaTurma = apps.get_model('precos', 'EntradaTurma')
    existentes = set(EntradaTurma.objects.values_list('aluna_id', 'turma_id'))
    novas = []

    for aluna in Aluna.objects.all().prefetch_related('turmas'):
        for turma in aluna.turmas.all().order_by('-valor_mensalidade', 'nome'):
            if (aluna.pk, turma.pk) not in existentes:
                novas.append(EntradaTurma(aluna=aluna, turma=turma, data_entrada=aluna.data_matricula))

    EntradaTurma.objects.bulk_create(novas)


